let file = """{"version":3,"file":"vRekaZIndex-DzVm4mHl.js","names":[],"sources":["../../src/components/dialog/vRekaZIndex.ts"],"sourcesContent":["import { ZIndex } from '@primeuix/utils/zindex'\nimport type { Directive } from 'vue'\n\n/** Shared modal stacking sequence; later registrations cover earlier ones. */\nexport const MODAL_Z_KEY = 'modal'\nexport const MODAL_Z_BASE = 1700\n/** Toasts stay above every modal layer, whichever opened first. */\nexport const TOAST_Z_INDEX = 9999\n\n// Dialogs and other overlays open in any order, and each portals with the\n// same static z-1700 class. Registering an element with the shared ZIndex\n// counter (key 'modal', base 1700) gives every open overlay its own step in\n// one stacking sequence, so whichever opened last covers the rest.\nexport const vRekaZIndex: Directive<HTMLElement> = {\n  mounted(el) {\n    ZIndex.set(MODAL_Z_KEY, el, MODAL_Z_BASE)\n  },\n  updated(el, { value, oldValue }) {\n    if (value === oldValue) return\n    ZIndex.clear(el)\n    ZIndex.set(MODAL_Z_KEY, el, MODAL_Z_BASE)\n  },\n  beforeUnmount(el) {\n    ZIndex.clear(el)\n  }\n}\n"],"mappings":"yFAIA,IAAa,EAAc,QACd,EAAe,KAEf,EAAgB,KAMhB,EAAsC,CACjD,QAAQ,EAAI,CACV,EAAO,IAAI,EAAa,EAAI,CAAY,CAC1C,EACA,QAAQ,EAAI,CAAE,QAAO,YAAY,CAC3B,IAAU,IACd,EAAO,MAAM,CAAE,EACf,EAAO,IAAI,EAAa,EAAI,CAAY,EAC1C,EACA,cAAc,EAAI,CAChB,EAAO,MAAM,CAAE,CACjB,CACF"}"""

